            ["id_chi_tiet_cha" => null, "so_luong" => 3, "don_gia" => 5600, "ghi_chu" => "Ít ngọt", "id_hoa_don" => 210, "id_san_pham" => 22, "tinh_trang" => 0, "created_at" => "2026-07-21 18:58:00", "updated_at" => "2026-07-21 18:58:00"]
        ];

        DB::statement('SET FOREIGN_KEY_CHECKS=0;');
        DB::table('chi_tiet_hoa_dons')->truncate();
        DB::statement('SET FOREIGN_KEY_CHECKS=1;');

        foreach ($data as &$item) {
            $product = DB::table('san_phams')->where('id', $item['id_san_pham'])->first();
            if ($product) {
                $item['don_gia'] = $product->gia_ban;
            }
        }
        unset($item);

        DB::table('chi_tiet_hoa_dons')->insert($data);

        $hoaDons = DB::table('hoa_dons')->get();
        foreach ($hoaDons as $hoaDon) {
            $tong_tien = DB::table('chi_tiet_hoa_dons')
                ->where('id_hoa_don', $hoaDon->id)
                ->select(DB::raw('SUM(so_luong * don_gia) as tong'))
                ->value('tong') ?: 0;

            $so_tien_giam = 0;
            if ($hoaDon->id_voucher) {
                $voucher = DB::table('vouchers')->where('id', $hoaDon->id_voucher)->first();
                if ($voucher) {
                    if ($voucher->loai_giam === 1) {
                        $so_tien_giam = ($tong_tien * $voucher->so_giam_gia) / 100;
                        if (isset($voucher->so_tien_toi_da) && $voucher->so_tien_toi_da > 0 && $so_tien_giam > $voucher->so_tien_toi_da) {
                            $so_tien_giam = $voucher->so_tien_toi_da;
                        }
                    } else {
                        $so_tien_giam = $voucher->so_giam_gia;
                    }
                }
            }

            $tong_tien_sau_giam = max(0, $tong_tien - $so_tien_giam);

            DB::table('hoa_dons')->where('id', $hoaDon->id)->update([
                'tien_truoc_giam' => $tong_tien,
                'so_tien_giam'    => $so_tien_giam,
                'tong_tien'       => $tong_tien_sau_giam,
            ]);
        }
